   288→        // Draw shape function
   289→        function drawShape() {
   290→            const x = Math.random() * (canvas.width - 200) + 100;
   291→            const y = Math.random() * (canvas.height - 200) + 100;
   292→            const size = 50;
   293→
   294→            const color = hexToRgba(colorPicker.value, opacitySlider.value / 100);
   295→            const rotation = (rotationSlider.value * Math.PI) / 180;
   296→            const scale = scaleSlider.value / 100;
   297→
   298→            ctx.save();
   299→            ctx.globalCompositeOperation = blendMode.value;
   300→            ctx.translate(x, y);
   301→            ctx.rotate(rotation);
   302→            ctx.scale(scale, scale);
   303→
   304→            ctx.fillStyle = color;
   305→            ctx.strokeStyle = color;
   306→            ctx.lineWidth = 3;
   307→
   308→            switch(shapeType.value) {
   309→                case 'rect':
   310→                    ctx.fillRect(-size/2, -size/2, size, size);
   311→                    break;
   312→                case 'circle':
   313→                    ctx.beginPath();
   314→                    ctx.arc(0, 0, size/2, 0, Math.PI * 2);
   315→                    ctx.fill();
   316→                    break;
   317→                case 'triangle':
   318→                    ctx.beginPath();
   319→                    ctx.moveTo(0, -size/2);
   320→                    ctx.lineTo(size/2, size/2);
   321→                    ctx.lineTo(-size/2, size/2);
   322→                    ctx.closePath();
   323→                    ctx.fill();
   324→                    break;
   325→                case 'line':
   326→                    ctx.beginPath();
   327→                    ctx.moveTo(-size/2, -size/2);
   328→                    ctx.lineTo(size/2, size/2);
   329→                    ctx.stroke();
   330→                    break;
   331→                case 'polygon':
   332→                    const sides = 6;
   333→                    ctx.beginPath();
   334→                    for (let i = 0; i < sides; i++) {
   335→                        const angle = (i * 2 * Math.PI) / sides;
   336→                        const px = (size/2) * Math.cos(angle);
   337→                        const py = (size/2) * Math.sin(angle);
   338→                        if (i === 0) ctx.moveTo(px, py);
   339→                        else ctx.lineTo(px, py);
   340→                    }
   341→                    ctx.closePath();
   342→                    ctx.fill();
   343→                    break;
   344→            }
   345→
   346→            ctx.restore();
   347→        }
   348→
   349→        // Clear canvas
   350→        function clearCanvas() {
   351→            ctx.clearRect(0, 0, canvas.width, canvas.height);
   352→        }
   353→
   354→        // Animation
   355→        let animating = false;
   356→        let animationId;
   357→
   358→        function animate() {
   359→            if (!animating) return;
   360→
   361→            // Randomize some values for interesting animations
   362→            rotationSlider.value = (parseInt(rotationSlider.value) + 5) % 360;
   363→            rotationValue.textContent = rotationSlider.value + '°';
   364→
   365→            drawShape();
   366→
   367→            animationId = setTimeout(() => {
   368→                requestAnimationFrame(animate);
   369→            }, 100);
   370→        }
   371→
   372→        function toggleAnimation() {
   373→            animating = !animating;
   374→            if (animating) {
   375→                animateBtn.textContent = 'Stop Animation';
   376→                animateBtn.style.background = '#e74c3c';
   377→                animate();
   378→            } else {
   379→                animateBtn.textContent = 'Animate Shapes';
   380→                animateBtn.style.background = '#667eea';
   381→                clearTimeout(animationId);
   382→            }
   383→        }
   384→
   385→        // Event listeners
   386→        drawBtn.addEventListener('click', drawShape);
   387→        clearBtn.addEventListener('click', clearCanvas);
   388→        animateBtn.addEventListener('click', toggleAnimation);
   389→
   390→        // Canvas click to draw
   391→        canvas.addEventListener('click', drawShape);
   392→
   393→        // Draw initial shape
   394→        drawShape();
   395→    </script>
   396→</body>
