   401→```javascript
   402→// navigation.js - Mobile menu behavior
   403→(function() {
   404→  const navToggle = document.querySelector('.nav-toggle');
   405→  const navMenu = document.querySelector('.nav-menu');
   406→
   407→  if (!navToggle || !navMenu) return;
   408→
   409→  navToggle.addEventListener('click', () => {
   410→    const isExpanded = navToggle.getAttribute('aria-expanded') === 'true';
   411→
   412→    navToggle.setAttribute('aria-expanded', !isExpanded);
   413→    navMenu.setAttribute('aria-expanded', !isExpanded);
   414→  });
   415→
   416→  // Close menu on Escape key
   417→  document.addEventListener('keydown', (e) => {
   418→    if (e.key === 'Escape' && navMenu.getAttribute('aria-expanded') === 'true') {
   419→      navToggle.setAttribute('aria-expanded', 'false');
   420→      navMenu.setAttribute('aria-expanded', 'false');
   421→      navToggle.focus();
   422→    }
   423→  });
   424→
   425→  // Close menu when clicking outside
   426→  document.addEventListener('click', (e) => {
   427→    if (!navToggle.contains(e.target) && !navMenu.contains(e.target)) {
   428→      navToggle.setAttribute('aria-expanded', 'false');
   429→      navMenu.setAttribute('aria-expanded', 'false');
   430→    }
   431→  });
   432→})();
   433→```
