   667→### Accessible Hamburger Menu
   668→
   669→```javascript
   670→// Source: Accessibility Matters - Mobile Navigation
   671→// https://a11ymatters.com/pattern/mobile-nav/
   672→
   673→(function() {
   674→  'use strict';
   675→
   676→  const menuButton = document.querySelector('[aria-controls="nav-menu"]');
   677→  const menu = document.getElementById('nav-menu');
   678→
   679→  if (!menuButton || !menu) return;
   680→
   681→  // Toggle menu
   682→  menuButton.addEventListener('click', function() {
   683→    const isExpanded = this.getAttribute('aria-expanded') === 'true';
   684→    this.setAttribute('aria-expanded', !isExpanded);
   685→  });
   686→
   687→  // Close on Escape
   688→  document.addEventListener('keydown', function(e) {
   689→    if (e.key === 'Escape' && menuButton.getAttribute('aria-expanded') === 'true') {
   690→      menuButton.setAttribute('aria-expanded', 'false');
   691→      menuButton.focus();
   692→    }
   693→  });
   694→
   695→  // Close when clicking outside
   696→  document.addEventListener('click', function(e) {
   697→    if (!menuButton.contains(e.target) && !menu.contains(e.target)) {
   698→      menuButton.setAttribute('aria-expanded', 'false');
   699→    }
   700→  });
   701→
   702→  // Trap focus in drawer when open
   703→  menu.addEventListener('keydown', function(e) {
   704→    if (e.key === 'Tab') {
   705→      const focusableElements = menu.querySelectorAll('a, button');
   706→      const firstElement = focusableElements[0];
   707→      const lastElement = focusableElements[focusableElements.length - 1];
   708→
   709→      if (e.shiftKey && document.activeElement === firstElement) {
   710→        e.preventDefault();
   711→        lastElement.focus();
   712→      } else if (!e.shiftKey && document.activeElement === lastElement) {
   713→        e.preventDefault();
   714→        firstElement.focus();
   715→      }
   716→    }
   717→  });
   718→})();
   719→```
