/* ========================================
   DESIGN SYSTEM - SHARED TOKENS
   Single source of truth for colors, typography, spacing, layout
   ======================================== */

:root {
    /* ========================================
       COLORS - Unified Green Palette
       ======================================== */

    /* Primary green (from landing page) */
    --color-primary: #2E7D32;
    --color-primary-dark: #1B5E20;
    --color-primary-light: #4CAF50;

    /* Neutral scale */
    --color-neutral-900: #2c3e50;
    --color-neutral-800: #34495e;
    --color-neutral-700: #555;
    --color-neutral-400: #999;
    --color-neutral-200: #e0e0e0;
    --color-neutral-100: #f8f9fa;
    --color-neutral-50: #ffffff;

    /* Accent purple (demoted from primary - for links/badges/buttons only) */
    --color-accent: #667eea;
    --color-accent-dark: #5568d3;

    /* Semantic colors */
    --color-danger: #e74c3c;
    --color-bg: #f5f5f5;

    /* ========================================
       TYPOGRAPHY - Fluid Scales
       ======================================== */

    /* Font families */
    --font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    --font-family-code: 'Cascadia Code', 'Fira Code', 'Monaco', 'Courier New', monospace;

    /* Font sizes - fluid with clamp() for accessibility */
    --text-h1: clamp(2rem, 1.5rem + 2vw, 3rem);
    --text-h2: clamp(1.5rem, 1.25rem + 1vw, 2rem);
    --text-h3: clamp(1.25rem, 1.125rem + 0.5vw, 1.5rem);
    --text-base: clamp(1rem, 0.9rem + 0.5vw, 1.125rem);
    --text-sm: clamp(0.875rem, 0.85rem + 0.25vw, 0.9375rem);

    /* ========================================
       SPACING - 8px Base Scale
       ======================================== */

    --space-xs: 0.5rem;     /* 8px */
    --space-sm: 1rem;       /* 16px */
    --space-md: 1.5rem;     /* 24px */
    --space-lg: 2rem;       /* 32px */
    --space-xl: 3rem;       /* 48px */
    --space-2xl: 4rem;      /* 64px */

    /* ========================================
       LAYOUT
       ======================================== */

    --max-width-content: 1200px;
    --max-width-text: 800px;
    --border-radius: 8px;
    --border-radius-lg: 12px;

    /* ========================================
       TRANSITIONS - Minimal/Fast
       ======================================== */

    --transition-fast: 0.15s ease;
    --transition-base: 0.2s ease;
    --transition-slow: 0.3s ease;

    /* ========================================
       SHADOWS
       ======================================== */

    --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.12), 0 1px 2px rgba(0, 0, 0, 0.08);
    --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.1);
    --shadow-lg: 0 10px 20px rgba(0, 0, 0, 0.15);
}

/* ========================================
   BASE RESET & ELEMENT STYLES
   ======================================== */

*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

body {
    font-family: var(--font-family);
    font-size: var(--text-base);
    line-height: 1.6;
    color: var(--color-neutral-900);
    background: var(--color-bg);
}

/* Prevent body scroll when nav is open */
body.nav-open {
    overflow: hidden;
}

/* ========================================
   SHARED NAVIGATION STYLES
   ======================================== */

.site-nav {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: var(--color-neutral-900);
    box-shadow: var(--shadow-md);
}

.nav-container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    max-width: var(--max-width-content);
    margin: 0 auto;
    padding: var(--space-sm) var(--space-md);
}

.nav-logo {
    font-size: var(--text-h3);
    font-weight: 700;
    color: var(--color-neutral-50);
    text-decoration: none;
    transition: color var(--transition-fast);
}

.nav-logo:hover {
    color: var(--color-primary-light);
}

.nav-toggle {
    display: none;
    background: none;
    border: none;
    cursor: pointer;
    padding: var(--space-xs);
    position: relative;
    width: 32px;
    height: 32px;
}

.nav-toggle:focus {
    outline: 2px solid var(--color-primary-light);
    outline-offset: 2px;
}

/* Hamburger icon - three lines using pseudo-elements */
.hamburger-icon {
    display: block;
    width: 24px;
    height: 2px;
    background: var(--color-neutral-50);
    position: relative;
    transition: background var(--transition-fast);
}

.hamburger-icon::before,
.hamburger-icon::after {
    content: '';
    position: absolute;
    width: 24px;
    height: 2px;
    background: var(--color-neutral-50);
    left: 0;
    transition: transform var(--transition-fast);
}

.hamburger-icon::before {
    top: -8px;
}

.hamburger-icon::after {
    bottom: -8px;
}

/* X animation when menu is open */
.nav-toggle[aria-expanded="true"] .hamburger-icon {
    background: transparent;
}

.nav-toggle[aria-expanded="true"] .hamburger-icon::before {
    transform: translateY(8px) rotate(45deg);
}

.nav-toggle[aria-expanded="true"] .hamburger-icon::after {
    transform: translateY(-8px) rotate(-45deg);
}

.nav-menu {
    display: flex;
    list-style: none;
    gap: var(--space-md);
    align-items: center;
}

.nav-link {
    color: var(--color-neutral-50);
    text-decoration: none;
    font-weight: 500;
    padding: var(--space-xs) var(--space-sm);
    border-radius: var(--border-radius);
    transition: background var(--transition-fast), color var(--transition-fast);
    position: relative;
}

.nav-link:hover {
    background: rgba(255, 255, 255, 0.1);
    color: var(--color-primary-light);
}

.nav-link:focus {
    outline: 2px solid var(--color-primary-light);
    outline-offset: 2px;
}

/* Breadcrumb navigation for project pages */
.breadcrumb {
    display: flex;
    align-items: center;
    gap: var(--space-xs);
    padding: var(--space-sm) 0;
    color: var(--color-neutral-700);
    font-size: var(--text-sm);
}

.breadcrumb a {
    color: var(--color-primary);
    text-decoration: none;
    transition: color var(--transition-fast);
}

.breadcrumb a:hover {
    color: var(--color-primary-dark);
    text-decoration: underline;
}

.breadcrumb-separator {
    color: var(--color-neutral-400);
}

/* ========================================
   MOBILE NAVIGATION (< 768px)
   ======================================== */

@media (max-width: 768px) {
    .nav-toggle {
        display: block;
    }

    .nav-menu {
        position: fixed;
        top: 0;
        right: 0;
        bottom: 0;
        width: 280px;
        max-width: 80vw;
        background: var(--color-neutral-900);
        flex-direction: column;
        align-items: flex-start;
        padding: var(--space-2xl) var(--space-lg);
        box-shadow: -4px 0 10px rgba(0, 0, 0, 0.2);
        transform: translateX(100%);
        transition: transform var(--transition-slow);
    }

    .nav-menu[aria-expanded="true"] {
        transform: translateX(0);
    }

    .nav-link {
        width: 100%;
        padding: var(--space-sm);
    }
}

/* ========================================
   SHARED FOOTER STYLES
   ======================================== */

.site-footer {
    background: var(--color-neutral-900);
    color: var(--color-neutral-100);
    padding: var(--space-xl) var(--space-md);
    margin-top: var(--space-2xl);
    text-align: center;
}

.footer-nav {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: var(--space-lg);
    flex-wrap: wrap;
}

.site-footer a {
    color: var(--color-primary-light);
    text-decoration: none;
    font-weight: 500;
    transition: color var(--transition-fast);
}

.site-footer a:hover {
    color: var(--color-primary);
    text-decoration: underline;
}

/* ========================================
   SUBTLE ANIMATIONS
   ======================================== */

/* Card hover lift */
.card-hover {
    transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.card-hover:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-lg);
}

/* Link underline growth */
.link-underline {
    position: relative;
    text-decoration: none;
}

.link-underline::after {
    content: '';
    position: absolute;
    bottom: -2px;
    left: 0;
    width: 0;
    height: 2px;
    background: currentColor;
    transition: width var(--transition-base);
}

.link-underline:hover::after {
    width: 100%;
}

/* Button press feedback */
button,
.btn {
    transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}

button:active,
.btn:active {
    transform: scale(0.98);
}

/* ========================================
   NAVIGATION - ACCESSIBLE MOBILE MENU
   Handles hamburger toggle, keyboard navigation, focus trap, and scroll prevention
   ======================================== */

(function() {
    'use strict';

    // Query DOM elements
    const navToggle = document.querySelector('.nav-toggle');
    const navMenu = document.querySelector('.nav-menu');
    const body = document.body;

    if (!navToggle || !navMenu) {
        console.warn('Navigation toggle or menu not found');
        return;
    }

    // Get all focusable elements inside menu for focus trap
    function getFocusableElements() {
        return Array.from(
            navMenu.querySelectorAll(
                'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
            )
        );
    }

    // Toggle menu open/closed
    function toggleMenu() {
        const isExpanded = navToggle.getAttribute('aria-expanded') === 'true';
        const newState = !isExpanded;

        // Update aria-expanded on both toggle and menu
        navToggle.setAttribute('aria-expanded', newState);
        navMenu.setAttribute('aria-expanded', newState);

        // Prevent body scroll when menu is open
        if (newState) {
            body.classList.add('nav-open');
        } else {
            body.classList.remove('nav-open');
        }
    }

    // Close menu and return focus to toggle
    function closeMenu() {
        navToggle.setAttribute('aria-expanded', 'false');
        navMenu.setAttribute('aria-expanded', 'false');
        body.classList.remove('nav-open');
        navToggle.focus();
    }

    // Handle click on toggle button
    navToggle.addEventListener('click', function(e) {
        e.stopPropagation();
        toggleMenu();
    });

    // Close menu on Escape key
    document.addEventListener('keydown', function(e) {
        const isExpanded = navToggle.getAttribute('aria-expanded') === 'true';
        if (e.key === 'Escape' && isExpanded) {
            closeMenu();
        }
    });

    // Close menu when clicking outside (not on toggle or inside menu)
    document.addEventListener('click', function(e) {
        const isExpanded = navToggle.getAttribute('aria-expanded') === 'true';
        if (!isExpanded) return;

        const clickedInsideMenu = navMenu.contains(e.target);
        const clickedToggle = navToggle.contains(e.target);

        if (!clickedInsideMenu && !clickedToggle) {
            closeMenu();
        }
    });

    // Focus trap inside open drawer
    navMenu.addEventListener('keydown', function(e) {
        const isExpanded = navToggle.getAttribute('aria-expanded') === 'true';
        if (!isExpanded) return;
        if (e.key !== 'Tab') return;

        const focusableElements = getFocusableElements();
        if (focusableElements.length === 0) return;

        const firstElement = focusableElements[0];
        const lastElement = focusableElements[focusableElements.length - 1];
        const activeElement = document.activeElement;

        // Tab forward from last element - wrap to first
        if (!e.shiftKey && activeElement === lastElement) {
            e.preventDefault();
            firstElement.focus();
        }

        // Shift+Tab backward from first element - wrap to last
        if (e.shiftKey && activeElement === firstElement) {
            e.preventDefault();
            lastElement.focus();
        }
    });

    // Close menu when clicking on nav links (mobile UX)
    const navLinks = navMenu.querySelectorAll('.nav-link');
    navLinks.forEach(function(link) {
        link.addEventListener('click', function() {
            const isExpanded = navToggle.getAttribute('aria-expanded') === 'true';
            if (isExpanded && window.innerWidth <= 768) {
                // Small delay to allow navigation to start
                setTimeout(function() {
                    closeMenu();
                }, 150);
            }
        });
    });

    // Initialize aria-expanded to false
    navToggle.setAttribute('aria-expanded', 'false');
    navMenu.setAttribute('aria-expanded', 'false');

})();

