   287→        // Simple SHA-256 hash function
   288→        async function sha256(message) {
   289→            const msgBuffer = new TextEncoder().encode(message);
   290→            const hashBuffer = await crypto.subtle.digest('SHA-256', msgBuffer);
   291→            const hashArray = Array.from(new Uint8Array(hashBuffer));
