   555→        // Utility: Convert hex color to RGBA
   556→        function hexToRGBA(hex, alpha = 1.0) {
   557→            const r = parseInt(hex.substr(1, 2), 16) / 255;
   558→            const g = parseInt(hex.substr(3, 2), 16) / 255;
   559→            const b = parseInt(hex.substr(5, 2), 16) / 255;
   560→            return { r, g, b, a: alpha };
   561→        }
