  1150→                const v3x = getParam('mesh', 'triangle', 'v3x', 600);
  1151→                const v3y = getParam('mesh', 'triangle', 'v3y', 500);
  1152→
  1153→                // Get vertex colors from parameters
  1154→                const c1 = getColorParam('mesh', 'triangle', 'color1', '#ff0000');
  1155→                const c2 = getColorParam('mesh', 'triangle', 'color2', '#00ff00');
  1156→                const c3 = getColorParam('mesh', 'triangle', 'color3', '#0000ff');
  1157→
  1158→                // Create triangle mesh with vertex colors
  1159→                const verts = new Module.VectorFloat();
  1160→                const colors = new Module.VectorFloat();
  1161→                const indices = new Module.VectorInt();
  1162→
  1163→                // Triangle vertices
  1164→                [v1x, v1y, v2x, v2y, v3x, v3y].forEach(v => verts.push_back(v));
  1165→
  1166→                // Vertex colors (RGB + alpha)
  1167→                [c1.r, c1.g, c1.b, 1.0,
  1168→                 c2.r, c2.g, c2.b, 1.0,
  1169→                 c3.r, c3.g, c3.b, 1.0
  1170→                ].forEach(v => colors.push_back(v));
  1171→
  1172→                // Triangle indices
  1173→                [0, 1, 2].forEach(v => indices.push_back(v));
  1174→
  1175→                const paint = new Module.PaintWrapper();
  1176→                wasmCanvas.drawMesh(verts, colors, new Module.VectorFloat(), indices, paint);
  1177→
  1178→                verts.delete();
  1179→                colors.delete();
  1180→                indices.delete();
  1181→
  1182→                updateCanvasDisplay();
  1183→            },
  1184→
  1185→            'poly-spiral': () => {
  1186→                wasmCanvas.clear(1.0, 1.0, 1.0, 1.0);  // White background
  1187→
  1188→                // Fixed parameters for static demo
  1189→                const cx = 400;
  1190→                const cy = 300;
  1191→                const startSides = 3;
  1192→                const numPolygons = 16;
  1193→                const initialRadius = 60;
  1194→                const radiusGrowth = 16;
  1195→                const rotationPerLayer = 18;
  1196→
  1197→                // Color palette (vibrant colors matching the demo image) with semi-transparency
  1198→                const colorPalette = [
  1199→                    { r: 0.6, g: 0.9, b: 0.7, a: 0.85 },   // Light Green/Mint (center triangle)
  1200→                    { r: 0.3, g: 0.2, b: 0.7, a: 0.85 },   // Dark Purple
  1201→                    { r: 0.5, g: 0.9, b: 0.5, a: 0.85 },   // Light Green
  1202→                    { r: 0.4, g: 0.3, b: 0.8, a: 0.85 },   // Purple
  1203→                    { r: 0.9, g: 0.3, b: 0.8, a: 0.85 },   // Magenta
  1204→                    { r: 0.9, g: 0.9, b: 0.3, a: 0.85 },   // Yellow
  1205→                    { r: 0.2, g: 0.8, b: 0.8, a: 0.85 },   // Cyan
  1206→                    { r: 1.0, g: 0.6, b: 0.7, a: 0.85 },   // Light Pink
  1207→                    { r: 0.8, g: 0.3, b: 0.4, a: 0.85 }    // Dark Pink/Rose
  1208→                ];
  1209→
  1210→                // Draw from OUTSIDE to INSIDE so inner polygons appear on top
  1211→                for (let i = numPolygons - 1; i >= 0; i--) {
  1212→                    const sides = startSides + i;  // Each polygon has one more side
  1213→                    const radius = initialRadius + (i * radiusGrowth);  // Radius grows outward
  1214→                    const rotation = (rotationPerLayer * i * Math.PI) / 180;  // Accumulate rotation
  1215→
  1216→                    // Get color from palette (cycle through colors)
  1217→                    const color = colorPalette[i % colorPalette.length];
  1218→
  1219→                    // Create polygon points
  1220→                    const points = new Module.VectorFloat();
  1221→                    for (let v = 0; v < sides; v++) {
  1222→                        const angle = (v * 2 * Math.PI) / sides + rotation;
  1223→                        const x = radius * Math.cos(angle);
  1224→                        const y = radius * Math.sin(angle);
  1225→                        points.push_back(x);
  1226→                        points.push_back(y);
  1227→                    }
  1228→
  1229→                    // Draw polygon with transformation
  1230→                    wasmCanvas.save();
  1231→                    wasmCanvas.translate(cx, cy);
  1232→                    wasmCanvas.drawConvexPolygon(points, color.r, color.g, color.b, color.a);
  1233→                    wasmCanvas.restore();
  1234→
  1235→                    points.delete();
  1236→                }
  1237→
  1238→                updateCanvasDisplay();
  1239→            }
  1240→        };
