    31→    --color-bg: #f5f5f5;
    32→
    33→    /* ========================================
    34→       TYPOGRAPHY - Fluid Scales
    35→       ======================================== */
    36→
    37→    /* Font families */
    38→    --font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    39→    --font-family-code: 'Cascadia Code', 'Fira Code', 'Monaco', 'Courier New', monospace;
    40→
    41→    /* Font sizes - fluid with clamp() for accessibility */
    42→    --text-h1: clamp(2rem, 1.5rem + 2vw, 3rem);
    43→    --text-h2: clamp(1.5rem, 1.25rem + 1vw, 2rem);
    44→    --text-h3: clamp(1.25rem, 1.125rem + 0.5vw, 1.5rem);
    45→    --text-base: clamp(1rem, 0.9rem + 0.5vw, 1.125rem);
    46→    --text-sm: clamp(0.875rem, 0.85rem + 0.25vw, 0.9375rem);
    47→
    48→    /* ========================================
    49→       SPACING - 8px Base Scale
    50→       ======================================== */
    51→
    52→    --space-xs: 0.5rem;     /* 8px */
    53→    --space-sm: 1rem;       /* 16px */
    54→    --space-md: 1.5rem;     /* 24px */
    55→    --space-lg: 2rem;       /* 32px */
    56→    --space-xl: 3rem;       /* 48px */
    57→    --space-2xl: 4rem;      /* 64px */
    58→
    59→    /* ========================================
    60→       LAYOUT
    61→       ======================================== */
    62→
    63→    --max-width-content: 1200px;
    64→    --max-width-text: 800px;
    65→    --border-radius: 8px;
    66→    --border-radius-lg: 12px;
    67→
    68→    /* ========================================
