    99→    color: var(--color-neutral-900);
   100→    background: var(--color-bg);
   101→}
   102→
   103→/* Prevent body scroll when nav is open */
   104→body.nav-open {
   105→    overflow: hidden;
   106→}
   107→
   108→/* ========================================
   109→   SHARED NAVIGATION STYLES
   110→   ======================================== */
   111→
   112→.site-nav {
