   118→}
   119→
   120→.nav-container {
   121→    display: flex;
   122→    align-items: center;
   123→    justify-content: space-between;
   124→    max-width: var(--max-width-content);
   125→    margin: 0 auto;
   126→    padding: var(--space-sm) var(--space-md);
   127→}
   128→
