   138→    color: var(--color-primary-light);
   139→}
   140→
   141→.nav-toggle {
   142→    display: none;
   143→    background: none;
   144→    border: none;
   145→    cursor: pointer;
   146→    padding: var(--space-xs);
   147→    position: relative;
   148→    width: 32px;
   149→    height: 32px;
   150→}
   151→
   152→.nav-toggle:focus {
   153→    outline: 2px solid var(--color-primary-light);
   154→    outline-offset: 2px;
   155→}
   156→
   157→/* Hamburger icon - three lines using pseudo-elements */
   158→.hamburger-icon {
   159→    display: block;
   160→    width: 24px;
   161→    height: 2px;
   162→    background: var(--color-neutral-50);
   163→    position: relative;
   164→    transition: background var(--transition-fast);
   165→}
   166→
   167→.hamburger-icon::before,
   168→.hamburger-icon::after {
   169→    content: '';
   170→    position: absolute;
   171→    width: 24px;
   172→    height: 2px;
   173→    background: var(--color-neutral-50);
   174→    left: 0;
   175→    transition: transform var(--transition-fast);
   176→}
   177→
   178→.hamburger-icon::before {
   179→    top: -8px;
   180→}
   181→
   182→.hamburger-icon::after {
   183→    bottom: -8px;
   184→}
