   222→    outline: 2px solid var(--color-primary-light);
   223→    outline-offset: 2px;
   224→}
   225→
   226→/* Breadcrumb navigation for project pages */
   227→.breadcrumb {
   228→    display: flex;
   229→    align-items: center;
   230→    gap: var(--space-xs);
   231→    padding: var(--space-sm) 0;
   232→    color: var(--color-neutral-700);
