   248→    color: var(--color-neutral-400);
   249→}
   250→
   251→/* ========================================
   252→   MOBILE NAVIGATION (< 768px)
   253→   ======================================== */
   254→
   255→@media (max-width: 768px) {
   256→    .nav-toggle {
   257→        display: block;
   258→    }
   259→
   260→    .nav-menu {
   261→        position: fixed;
   262→        top: 0;
   263→        right: 0;
   264→        bottom: 0;
   265→        width: 280px;
   266→        max-width: 80vw;
   267→        background: var(--color-neutral-900);
   268→        flex-direction: column;
   269→        align-items: flex-start;
   270→        padding: var(--space-2xl) var(--space-lg);
   271→        box-shadow: -4px 0 10px rgba(0, 0, 0, 0.2);
   272→        transform: translateX(100%);
   273→        transition: transform var(--transition-slow);
   274→    }
   275→
   276→    .nav-menu[aria-expanded="true"] {
   277→        transform: translateX(0);
   278→    }
   279→
   280→    .nav-link {
   281→        width: 100%;
   282→        padding: var(--space-sm);
   283→    }
   284→}
   285→
   286→/* ========================================
   287→   SHARED FOOTER STYLES
   288→   ======================================== */
   289→
   290→.site-footer {
   291→    background: var(--color-neutral-900);
   292→    color: var(--color-neutral-100);
   293→    padding: var(--space-xl) var(--space-md);
   294→    margin-top: var(--space-2xl);
   295→    text-align: center;
   296→}
   297→
   298→.footer-nav {
