   304→}
   305→
   306→.site-footer a {
   307→    color: var(--color-primary-light);
   308→    text-decoration: none;
   309→    font-weight: 500;
   310→    transition: color var(--transition-fast);
   311→}
   312→
   313→.site-footer a:hover {
   314→    color: var(--color-primary);
   315→    text-decoration: underline;
   316→}
   317→
   318→/* ========================================
   319→   SUBTLE ANIMATIONS
   320→   ======================================== */
   321→
   322→/* Card hover lift */
   323→.card-hover {
   324→    transition: transform var(--transition-base), box-shadow var(--transition-base);
   325→}
   326→
   327→.card-hover:hover {
   328→    transform: translateY(-4px);
   329→    box-shadow: var(--shadow-lg);
   330→}
   331→
   332→/* Link underline growth */
   333→.link-underline {
   334→    position: relative;
   335→    text-decoration: none;
   336→}
   337→
   338→.link-underline::after {
   339→    content: '';
   340→    position: absolute;
   341→    bottom: -2px;
   342→    left: 0;
   343→    width: 0;
   344→    height: 2px;
