   707→        function updateCanvasDisplay() {
   708→            if (!wasmCanvas || !Module) return;
   709→
   710→            try {
   711→                const width = wasmCanvas.getWidth();
   712→                const height = wasmCanvas.getHeight();
   713→                const pixelPtr = wasmCanvas.getPixelsPtr();
   714→                const pixelCount = width * height;
   715→
   716→                let wasmPixels;
   717→                if (Module.HEAPU32) {
   718→                    wasmPixels = new Uint32Array(Module.HEAPU32.buffer, pixelPtr, pixelCount);
   719→                } else if (Module.HEAPU8) {
   720→                    wasmPixels = new Uint32Array(Module.HEAPU8.buffer, pixelPtr, pixelCount);
   721→                }
   722→
   723→                const imageData = ctx.createImageData(width, height);
   724→                const data = imageData.data;
   725→
   726→                // Convert premultiplied ARGB to non-premultiplied RGBA
   727→                for (let i = 0; i < pixelCount; i++) {
   728→                    const argb = wasmPixels[i];
   729→                    const a = (argb >> 24) & 0xFF;
   730→                    let r = (argb >> 16) & 0xFF;
   731→                    let g = (argb >> 8) & 0xFF;
   732→                    let b = argb & 0xFF;
   733→
   734→                    // Unpremultiply RGB by alpha
   735→                    if (a > 0 && a < 255) {
   736→                        r = Math.round((r * 255) / a);
   737→                        g = Math.round((g * 255) / a);
   738→                        b = Math.round((b * 255) / a);
   739→                    }
   740→
   741→                    const idx = i * 4;
   742→                    data[idx] = r;
   743→                    data[idx + 1] = g;
   744→                    data[idx + 2] = b;
   745→                    data[idx + 3] = a;
   746→                }
   747→
   748→                ctx.putImageData(imageData, 0, 0);
   749→            } catch (e) {
   750→                console.error('Error updating canvas:', e);
   751→            }
   752→        }
