/* Documentation Pages - Main Styles */
/* Builds on design-system.css - uses tokens for colors, typography, spacing */

/* ========================================
   LAYOUT & CONTAINER
   ======================================== */

.doc-container {
    max-width: var(--max-width-content);
    margin: 0 auto;
    padding: 0 var(--space-md);
}

/* ========================================
   HEADER
   ======================================== */

.doc-header {
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
    color: var(--color-neutral-50);
    padding: var(--space-xl) 0 var(--space-lg);
    margin-bottom: var(--space-lg);
    box-shadow: var(--shadow-md);
}

.doc-header h1 {
    font-size: var(--text-h1);
    font-weight: 700;
    margin-bottom: var(--space-xs);
}

.doc-header p {
    font-size: var(--text-base);
    opacity: 0.9;
}

/* ========================================
   NAVIGATION & BREADCRUMB
   ======================================== */

.breadcrumb {
    margin-bottom: var(--space-lg);
    padding: 0.75rem var(--space-sm);
    background-color: var(--color-neutral-50);
    border-radius: var(--border-radius);
    box-shadow: var(--shadow-sm);
}

.breadcrumb a {
    color: var(--color-primary);
    text-decoration: none;
    transition: color var(--transition-base);
}

.breadcrumb a:hover {
    color: var(--color-primary-dark);
    text-decoration: underline;
}

.breadcrumb .separator {
    margin: 0 var(--space-xs);
    color: var(--color-neutral-400);
}

/* ========================================
   CONTENT AREA
   ======================================== */

.content-wrapper {
    background-color: var(--color-neutral-50);
    border-radius: var(--border-radius);
    box-shadow: var(--shadow-md);
    padding: var(--space-lg);
    margin-bottom: var(--space-lg);
}

.content-section {
    max-width: var(--max-width-text);
    margin: 0 auto var(--space-lg);
}

.content-section h2 {
    font-size: var(--text-h2);
    color: var(--color-neutral-900);
    margin-bottom: var(--space-sm);
    padding-bottom: var(--space-xs);
    border-bottom: 2px solid var(--color-primary);
}

.content-section p {
    margin-bottom: var(--space-sm);
    line-height: 1.8;
}

/* ========================================
   TABS
   ======================================== */

.tabs {
    margin: var(--space-lg) 0;
}

[role="tablist"] {
    display: flex;
    gap: 0;
    border-bottom: 2px solid var(--color-neutral-200);
    margin-bottom: 0;
    flex-wrap: wrap;
}

[role="tab"] {
    background: transparent;
    border: none;
    border-bottom: 3px solid transparent;
    padding: 0.75rem var(--space-md);
    font-size: var(--text-base);
    font-weight: 500;
    color: var(--color-neutral-700);
    cursor: pointer;
    transition: all var(--transition-base);
    position: relative;
    margin-bottom: -2px;
}

[role="tab"]:hover {
    color: var(--color-primary);
    background-color: var(--color-neutral-100);
}

[role="tab"]:focus {
    outline: 2px solid var(--color-primary);
    outline-offset: -2px;
    z-index: 1;
}

[role="tab"][aria-selected="true"] {
    color: var(--color-primary);
    border-bottom-color: var(--color-primary);
    background-color: var(--color-neutral-50);
    font-weight: 600;
}

[role="tabpanel"] {
    padding: var(--space-md);
    background-color: var(--color-neutral-50);
    border-radius: 0 0 var(--border-radius) var(--border-radius);
}

[role="tabpanel"][hidden] {
    display: none;
}

/* ========================================
   DEMO SECTION
   ======================================== */

.demo-section {
    margin: var(--space-lg) 0;
    padding: var(--space-md);
    background-color: var(--color-bg);
    border-radius: var(--border-radius);
    border: 1px solid var(--color-neutral-200);
}

.demo-section h3 {
    font-size: var(--text-h3);
    color: var(--color-neutral-900);
    margin-bottom: var(--space-sm);
}

.iframe-container,
.demo-container {
    position: relative;
    width: 100%;
    background-color: var(--color-neutral-50);
    border-radius: var(--border-radius);
    overflow: hidden;
    box-shadow: var(--shadow-md);
}

.iframe-container iframe,
.demo-container iframe,
.demo-frame {
    display: block;
    width: 100%;
    height: 600px;
    border: none;
}

/* ========================================
   FOOTER
   ======================================== */

.docs-footer {
    background-color: var(--color-neutral-900);
    color: var(--color-neutral-50);
    padding: var(--space-lg);
    text-align: center;
    margin-top: var(--space-2xl);
    border-radius: var(--border-radius);
}

.docs-footer p {
    margin-bottom: var(--space-sm);
    opacity: 0.9;
}

.footer-nav {
    display: flex;
    justify-content: center;
    gap: var(--space-md);
    flex-wrap: wrap;
}

.footer-nav a {
    color: var(--color-primary-light);
    text-decoration: none;
    font-weight: 500;
    transition: color var(--transition-base);
}

.footer-nav a:hover {
    color: var(--color-primary);
    text-decoration: underline;
}

/* ========================================
   RESPONSIVE BREAKPOINTS
   ======================================== */

@media (min-width: 768px) and (max-width: 1024px) {
    .doc-container {
        padding: 0 var(--space-lg);
    }

    .content-wrapper {
        padding: var(--space-md);
    }
}

@media (max-width: 768px) {
    .doc-header h1 {
        font-size: clamp(1.75rem, 4vw, 2rem);
    }

    .doc-header p {
        font-size: var(--text-sm);
    }

    .content-wrapper {
        padding: var(--space-md);
    }

    [role="tab"] {
        padding: 0.6rem var(--space-sm);
        font-size: var(--text-sm);
    }

    [role="tabpanel"] {
        padding: var(--space-sm);
    }

    .iframe-container iframe,
    .demo-container iframe,
    .demo-frame {
        height: 400px;
    }
}

@media (max-width: 480px) {
    .doc-container {
        padding: 0 15px;
    }

    .doc-header {
        padding: var(--space-lg) 0 var(--space-md);
    }

    .doc-header h1 {
        font-size: 1.5rem;
    }

    [role="tablist"] {
        flex-direction: column;
        border-bottom: none;
    }

    [role="tab"] {
        border-bottom: 1px solid var(--color-neutral-200);
        border-left: 3px solid transparent;
        text-align: left;
        margin-bottom: 0;
    }

    [role="tab"][aria-selected="true"] {
        border-left-color: var(--color-primary);
        border-bottom-color: var(--color-neutral-200);
    }
}

/* ========================================
   API REFERENCE STYLES
   ======================================== */

/* API Navigation for jump links */
.api-nav {
    background: var(--color-bg);
    padding: var(--space-md);
    border-radius: var(--border-radius);
    margin-bottom: var(--space-lg);
    border-left: 4px solid var(--color-primary);
}

.api-nav h3 {
    margin-top: 0;
    margin-bottom: var(--space-sm);
    color: var(--color-neutral-900);
    font-size: var(--text-h3);
}

.api-nav ul {
    list-style: none;
    padding: 0;
    margin: 0;
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--space-xs);
}

.api-nav li {
    margin: 0;
}

.api-nav a {
    color: var(--color-primary);
    text-decoration: none;
    font-weight: 500;
    display: block;
    padding: var(--space-xs);
    border-radius: var(--border-radius);
    transition: background var(--transition-base), color var(--transition-base);
}

.api-nav a:hover {
    color: var(--color-primary-dark);
    background: rgba(46, 125, 50, 0.1);
}

/* API Sections */
.api-section {
    margin-bottom: var(--space-xl);
    padding-bottom: var(--space-lg);
    border-bottom: 1px solid var(--color-neutral-200);
}

.api-section:last-child {
    border-bottom: none;
}

.api-section h2 {
    color: var(--color-neutral-900);
    font-size: var(--text-h2);
    margin-bottom: var(--space-xs);
    padding-bottom: var(--space-xs);
    border-bottom: 3px solid var(--color-primary);
}

.api-section > p {
    color: var(--color-neutral-700);
    line-height: 1.8;
    margin-bottom: var(--space-md);
}

/* API Table Wrapper with horizontal scroll */
.api-table-wrapper {
    overflow-x: auto;
    margin: var(--space-md) 0;
    border-radius: var(--border-radius);
    box-shadow: var(--shadow-md);
}

/* API Table */
.api-table {
    width: 100%;
    border-collapse: collapse;
    background: var(--color-neutral-50);
    font-size: var(--text-base);
}

.api-table thead {
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
    color: var(--color-neutral-50);
    position: sticky;
    top: 0;
    z-index: 10;
}

.api-table thead th {
    text-align: left;
    padding: var(--space-sm);
    font-weight: 600;
    font-size: var(--text-sm);
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.api-table tbody tr {
    border-bottom: 1px solid var(--color-neutral-200);
    transition: background-color var(--transition-base);
}

.api-table tbody tr:hover {
    background-color: var(--color-neutral-100);
}

.api-table tbody tr:last-child {
    border-bottom: none;
}

.api-table td {
    padding: var(--space-sm);
    vertical-align: top;
}

/* First column (function name) */
.api-table td:first-child {
    font-family: var(--font-family-code);
    font-weight: 600;
    color: var(--color-primary);
    white-space: nowrap;
    min-width: 150px;
}

/* Second column (signature) */
.api-table td:nth-child(2) {
    font-family: var(--font-family-code);
    font-size: var(--text-sm);
    color: var(--color-neutral-700);
    word-break: break-word;
}

/* Third column (description) */
.api-table td:nth-child(3) {
    color: var(--color-neutral-700);
    line-height: 1.6;
}

/* Factory function highlight */
.api-table tr.factory-function {
    background-color: rgba(46, 125, 50, 0.05);
}

.api-table tr.factory-function:hover {
    background-color: rgba(46, 125, 50, 0.1);
}

/* Code inline in tables */
.api-table code {
    background: var(--color-bg);
    padding: 0.2rem 0.4rem;
    border-radius: 3px;
    font-size: 0.9em;
    color: var(--color-danger);
}

/* Usage examples in API sections */
.api-section .code-snippet {
    margin: var(--space-lg) 0;
}

.api-section h3 {
    color: var(--color-neutral-900);
    font-size: var(--text-h3);
    margin-top: var(--space-lg);
    margin-bottom: var(--space-sm);
}

/* Responsive API Tables */
@media (max-width: 768px) {
    .api-nav ul {
        grid-template-columns: 1fr;
    }

    .api-table {
        font-size: var(--text-sm);
    }

    .api-table thead th {
        padding: 0.75rem var(--space-xs);
        font-size: 0.8rem;
    }

    .api-table td {
        padding: 0.75rem var(--space-xs);
    }

    .api-table td:first-child {
        min-width: 120px;
    }

    .api-table td:nth-child(2) {
        font-size: 0.75rem;
    }
}

@media (max-width: 480px) {
